assertions.check:
p=clients/northgate-clinic/site/definition/cold-designer-plan.md
s=clients/northgate-clinic/site/definition/sitemap.md
t=clients/northgate-clinic/site/definition/cold-designer-triage.md
test -f "$p" || { echo "no cold-designer plan at $p"; exit 1; }
test -f "$s" || { echo "no signed sitemap at $s -- independence cannot be judged"; exit 1; }
test -f "$t" || { echo "no triage at $t"; exit 1; }
sections() { awk '
  function emit(text,   n, i, parts, one) {
    n = split(text, parts, ";")
    for (i = 1; i <= n; i++) {
      one = tolower(parts[i]); gsub(/[^a-z0-9]+/, " ", one); gsub(/^ +| +$/, "", one)
      if (one != "") print one
    }
  }
  /^[[:space:]]*```/ { fence = !fence; next }
  fence { next }
  {
    text = ""
    if ($0 ~ /^[[:space:]]*#+[[:space:]]/) { text = $0; sub(/^[[:space:]]*#+[[:space:]]*/, "", text) }
    else if ($0 ~ /^[[:space:]]*([-*+]|[0-9]+[.)])[[:space:]]/) { text = $0; sub(/^[[:space:]]*([-*+]|[0-9]+[.)])[[:space:]]*/, "", text) }
    else if ($0 ~ /^[[:space:]]*\|/) { split($0, cell, "|"); text = cell[2]; if (text ~ /^[[:space:]]*:?-+/) text = "" }
    if (text != "") { structural = 1; emit(text) } else { plain[++np] = $0 }
  }
  END { if (!structural) for (i = 1; i <= np; i++) emit(plain[i]) }
' "$1" | sort -u; }
only=$(comm -23 <(sections "$p") <(sections "$s") | wc -l | tr -d " ")
if [ "$only" -lt 3 ]; then echo "the plan names only $only section(s) the signed sitemap does not -- it restates the sitemap rather than planning independently"; exit 1; fi
awk -F'|' -v plan="$p" '
  BEGIN { while ((getline line < plan) > 0) { line = tolower(line); gsub(/[^a-z0-9]+/, " ", line); body = body " " line } body = body " " }
  /^[[:space:]]*\|/ {
    if ($2 ~ /^[[:space:]]*:?-+/) next
    sec = $2; gsub(/^[[:space:]]+|[[:space:]]+$/, "", sec)
    if (sec == "" || sec == "Section") next
    n++
    low = tolower(sec); gsub(/[^a-z0-9]+/, " ", low); gsub(/^ +| +$/, "", low)
    c = split(low, w, " "); hits = 0; words = 0
    for (i = 1; i <= c; i++) { if (length(w[i]) < 4) continue; words++; if (index(body, " " w[i] " ")) hits++ }
    if (words == 0) { words = 1; if (index(body, " " low " ")) hits = 1 }
    if (hits == words) traced++
  }
  END {
    if (n == 0) { print "no triage rows to trace back to the plan"; exit 1 }
    if (traced < 2 || traced * 2 < n) { printf "only %d of %d triage rows name a section the plan planned\n", traced, n; exit 1 }
  }' "$t"
